/* ================================================================ views: grain → group → named screen */
const GROUPS=[["overview","Overview"],["data","Data"],["findings","Findings"],["pipeline","Pipeline"],["walk","Walkthrough"],["decide","Decide"]];
const PAGES={}, VIEWS={event:[],country:[],daily:[],hourly:[]};
/* VW(grain, group, id, short title, options)
   options: mod (one atlas module, header taken from it), subs, intro, blocks, sub (headline), lede, eyebrow,
            nrs (new renderers to run), kind (models|kpis|decisions|build|overview), s (status dot), src (notebook source) */
function VW(g,group,id,title,o={}){
  const r=g+"-"+id, m=o.mod?MODS[o.mod]:null;
  const v=Object.assign({grain:g,group,id,title},o);
  if(m&&!o.blocks) v.blocks=[M(o.mod,{subs:o.subs,intro:o.intro})];
  if(m){ if(v.sub===undefined) v.sub=m.title; if(v.lede===undefined) v.lede=m.lede; if(v.eyebrow===undefined) v.eyebrow=m.eyebrow; }
  v.mods=[...new Set((v.blocks||[]).filter(b=>b.mod).map(b=>b.mod).concat(o.mods||[]))];
  PAGES[r]=v; VIEWS[g].push(r);
}
const KPIS=h=>({html:'<div class="kpis">'+h+'</div>'});
const K=(c,b,s)=>'<div class="kpi '+c+'"><b>'+b+'</b><span>'+s+'</span></div>';
const GF=g=>({html:'<section class="blk"><h3>This grain in one card</h3><div class="gfacts" data-g="'+g+'"></div></section>'});

